import{_ as e,o as n,c as t,a0 as i}from"./chunks/framework.DCluYYrN.js";const k=JSON.parse('{"title":"Recovery dari bootloop","description":"","frontmatter":{},"headers":[],"relativePath":"id_ID/guide/rescue-from-bootloop.md","filePath":"id_ID/guide/rescue-from-bootloop.md"}'),s={name:"id_ID/guide/rescue-from-bootloop.md"};function l(o,a,d,m,r,u){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="recovery-dari-bootloop" tabindex="-1">Recovery dari bootloop <a class="header-anchor" href="#recovery-dari-bootloop" aria-label="Permalink to &quot;Recovery dari bootloop&quot;">​</a></h1><p>Saat mem-flash perangkat, kami mungkin menghadapi situasi di mana perangkat menjadi &quot;bata&quot;. Secara teori, jika Anda hanya menggunakan fastboot untuk mem-flash partisi boot atau menginstal modul yang tidak sesuai yang menyebabkan perangkat gagal melakukan booting, ini dapat dipulihkan dengan operasi yang sesuai. Dokumen ini bertujuan untuk memberikan beberapa metode darurat untuk membantu Anda pulih dari perangkat &quot;bricked&quot;.</p><h2 id="brick-saat-memflash-partisi-boot" tabindex="-1">Brick saat memflash partisi boot <a class="header-anchor" href="#brick-saat-memflash-partisi-boot" aria-label="Permalink to &quot;Brick saat memflash partisi boot&quot;">​</a></h2><p>Di KernelSU, situasi berikut dapat menyebabkan bata boot saat mem-flash partisi boot:</p><ol><li>Anda mem-flash image boot dalam format yang salah. Misalnya, jika format booting ponsel Anda adalah <code>gz</code>, tetapi Anda mem-flash image berformat <code>lz4</code>, maka ponsel tidak akan dapat melakukan booting.</li><li>Ponsel Anda perlu menonaktifkan verifikasi AVB agar dapat boot dengan benar (biasanya perlu menghapus semua data di ponsel).</li><li>Kernel Anda memiliki beberapa bug atau tidak cocok untuk flash ponsel Anda.</li></ol><p>Apa pun situasinya, Anda dapat memulihkannya dengan <strong>mem-flash gambar boot stok</strong>. Oleh karena itu, di awal tutorial instalasi, kami sangat menyarankan Anda untuk mem-backup stock boot Anda sebelum melakukan flashing. Jika Anda belum mencadangkan, Anda dapat memperoleh boot pabrik asli dari pengguna lain dengan perangkat yang sama dengan Anda atau dari firmware resmi.</p><h2 id="brick-disebabkan-modul" tabindex="-1">Brick disebabkan modul <a class="header-anchor" href="#brick-disebabkan-modul" aria-label="Permalink to &quot;Brick disebabkan modul&quot;">​</a></h2><p>Memasang modul dapat menjadi penyebab yang lebih umum dari bricking perangkat Anda, tetapi kami harus memperingatkan Anda dengan serius: <strong>Jangan memasang modul dari sumber yang tidak dikenal</strong>! Karena modul memiliki hak akses root, mereka berpotensi menyebabkan kerusakan permanen pada perangkat Anda!</p><h3 id="module-normal" tabindex="-1">Module normal <a class="header-anchor" href="#module-normal" aria-label="Permalink to &quot;Module normal&quot;">​</a></h3><p>Jika Anda telah mem-flash modul yang telah terbukti aman tetapi menyebabkan perangkat Anda gagal booting, maka situasi ini dapat dipulihkan dengan mudah di KernelSU tanpa rasa khawatir. KernelSU memiliki mekanisme bawaan untuk menyelamatkan perangkat Anda:</p><h4 id="volume-down" tabindex="-1">Recovery dengan menekan Volume Bawah <a class="header-anchor" href="#volume-down" aria-label="Permalink to &quot;Recovery dengan menekan Volume Bawah {#volume-down}&quot;">​</a></h4><p>Anda dapat mencoba menggunakan <strong>Safe Mode</strong> untuk menyelamatkan perangkat Anda. Setelah masuk ke Safe Mode, semua modul dinonaktifkan.</p><p>Ada dua cara untuk masuk ke Safe Mode:</p><ol><li>Mode Aman bawaan dari beberapa sistem; beberapa sistem memiliki Safe Mode bawaan yang dapat diakses dengan menekan lama tombol volume turun, sementara yang lain (seperti MIUI/HyperOS) dapat mengaktifkan Safe Mode di Recovery. Saat memasuki Safe Mode sistem, KernelSU juga akan masuk ke Safe Mode dan secara otomatis menonaktifkan modul.</li><li>Safe Mode bawaan dari KernelSU; metode pengoperasiannya adalah <strong>tekan tombol volume turun secara terus-menerus selama lebih dari tiga kali</strong> setelah layar boot pertama. Perhatikan bahwa ini adalah tekan-lepas, tekan-lepas, tekan-lepas, bukan tekan dan tahan.</li></ol><p>Setelah memasuki mode aman, semua modul pada halaman modul KernelSU Manager dinonaktifkan, tetapi Anda dapat melakukan operasi &quot;uninstall&quot; untuk menghapus semua modul yang mungkin menyebabkan masalah.</p><p>Mode aman bawaan diimplementasikan di kernel, jadi tidak ada kemungkinan peristiwa penting yang hilang karena intersepsi. Namun, untuk kernel non-GKI, integrasi kode secara manual mungkin diperlukan, dan Anda dapat merujuk ke dokumentasi resmi untuk mendapatkan panduan.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>KernelSU mendaftarkan pendengar tombol volume selama inisialisasi modul kernel (dimuat saat kernel menjalankan proses init dalam mode LKM), dan membatalkan pendaftarannya pada tahap <code>on_post_fs_data</code> (sebelum animasi boot). Anda perlu memahami waktunya dan dengan cepat menekan tombol volume turun tiga kali setelah layar boot pertama. Jika perangkat boot dengan cepat atau operasinya tidak tepat waktu, safe mode mungkin tidak terpicu.</p><p>Jika modul menulis kode yang tidak masuk akal di initrc yang menyebabkan perangkat gagal boot, kode-kode ini masih akan dijalankan bahkan dalam safe mode.</p></div><h4 id="manual-rescue" tabindex="-1">Penyelamatan Manual <a class="header-anchor" href="#manual-rescue" aria-label="Permalink to &quot;Penyelamatan Manual {#manual-rescue}&quot;">​</a></h4><p>Saat safe mode tidak dapat menyelesaikan masalah, Anda dapat mencoba penyelamatan manual. Pilih metode berikut berdasarkan status perangkat.</p><p><strong>Metode 1: Gunakan ksud untuk mengelola modul melalui ADB</strong></p><p>Jika perangkat bisa mendapatkan root shell via ADB, Anda bisa menggunakan baris perintah <code>ksud</code> langsung untuk menonaktifkan atau menghapus instalan modul yang bermasalah:</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Setelah memasang partisi <code>metadata</code> dan <code>data</code>, Anda bisa menjalankan perintah <code>/data/adb/ksud</code> di bawah mode Recovery untuk mengelola modul.</p><p>Karena perangkat GKI berbagi <code>init</code>, modul kernel KernelSU masih akan dimuat di bawah mode Recovery, Anda seharusnya bisa menggunakan sebagian besar fitur <code>ksud</code> (seperti mengatur fitur) secara normal.</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>adb shell</span></span>
<span class="line"><span>su</span></span>
<span class="line"><span>ksud module list          # Daftar semua modul</span></span>
<span class="line"><span>ksud module disable &lt;id&gt;  # Nonaktifkan modul yang bermasalah</span></span>
<span class="line"><span>ksud module uninstall &lt;id&gt; # Atau langsung uninstall</span></span>
<span class="line"><span>reboot</span></span></code></pre></div><p><strong>Metode 2: Bersihkan manual melalui Recovery</strong></p><p>Jika Anda tidak dapat masuk ke sistem (bahkan ADB tidak dapat dihubungkan), Anda membutuhkan Recovery pihak ketiga (seperti TWRP) di perangkat.</p><p>Pemuatan modul KernelSU bergantung pada file injeksi init.rc di sisi kernel dan proses ksud di user space. Setelah menghapus file-file ini dan melakukan reboot, KernelSU tidak akan memuat modul apa pun.</p><p><strong>Langkah-langkah operasi:</strong></p><ol><li>Masuk ke Recovery (seperti TWRP).</li><li>Pasang partisi data:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount /data</span></span></code></pre></div>(Anda mungkin perlu mendekripsi partisi data terlebih dahulu. Operasi spesifik tergantung pada perangkat dan metode dekripsi.)</li><li>Hapus ksud untuk mencegah pemuatan modul:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -f /data/adb/ksud</span></span></code></pre></div></li><li>(Opsional) Pasang partisi metadata dan hapus file injeksi init.rc yang dihasilkan oleh modul:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount /metadata</span></span>
<span class="line"><span>rm -f /metadata/ksu/modules.rc</span></span>
<span class="line"><span>rm -f /metadata/watchdog/ksu/modules.rc</span></span></code></pre></div></li><li>Reboot perangkat:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reboot</span></span></code></pre></div></li></ol><p>KernelSU akan melewati pemuatan semua modul setelah reboot. Setelah masuk ke sistem, Anda bisa membuka kembali KernelSU manager untuk menangani masalah modul.</p><h3 id="format-data-atau-modul-berbahaya-lainnya" tabindex="-1">Format data atau modul berbahaya lainnya <a class="header-anchor" href="#format-data-atau-modul-berbahaya-lainnya" aria-label="Permalink to &quot;Format data atau modul berbahaya lainnya&quot;">​</a></h3><p>Jika metode di atas tidak dapat menyelamatkan perangkat Anda, kemungkinan besar modul yang Anda instal memiliki operasi jahat atau telah merusak perangkat Anda melalui cara lain. Dalam hal ini, hanya ada dua saran:</p><ol><li>Hapus data dan flash sistem resmi sepenuhnya.</li><li>Konsultasikan layanan purna jual.</li></ol>`,32)])])}const b=e(s,[["render",l]]);export{k as __pageData,b as default};
